      "label": "Tech_FragmentedDownloads",
      "span": "I thought I already download the file but I still get an additional download",
      "rationale": "This describes a further in-game download after the reviewer believed the game file had already been downloaded, matching fragmented downloads."
    }
  ],
  "invoked_web_search": false,
