}

{
  "analysis": "The review describes repeated failed attempts to clear a level, which satisfies T_Grinding. It also alleges that outcomes are manipulated to induce spending, satisfying P_IllusionOfControl, and reports repeated near-wins, satisfying P_OptimismAndFrequencyBiases under the near-miss frequency rule. The constant purchase prompts do not establish M_EasyToPurchase because the review does not say they interrupt play, appear after insufficient funds, or require dismissal; they are solicitation volume alone. M_PayToProgress is rejected because payment is not explicitly described as required for progress.",
  "labels": [
    {
      "label": "T_Grinding",
      "span": "a level is failed 1 or 2 moves from winning. 20 or 30 times in a row.",
      "rationale": "The span describes repeated attempts and failures while trying to progress past a level."
    },
    {
      "label": "P_IllusionOfControl",
      "span": "almost every game is rigged to make you spend",
      "rationale": "The reviewer alleges that the game manipulates outcome determination to influence continued play and spending."
    },
    {
      "label": "P_OptimismAndFrequencyBiases",
      "span": "a level is failed 1 or 2 moves from winning. 20 or 30 times in a row.",
      "rationale": "The span describes repeated near-wins, an experienced clustering of almost-successes that can sustain optimism and further attempts."
    }
  ],
  "invoked_web_search": false,
  "search_query": null,
  "search_result": null
}

{
